CREATE OR REPLACE FUNCTION public.av2_guard_attendance_record_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE', 'DELETE')
     and public.av2_attendance_month_is_closed(old.emp_id, old.report_date) then
    raise exception 'attendance_month_locked' using errcode = '55000';
  end if;

  if tg_op in ('INSERT', 'UPDATE')
     and public.av2_attendance_month_is_closed(new.emp_id, new.report_date) then
    raise exception 'attendance_month_locked' using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.av2_guard_course_date_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_emp_id bigint;
  v_role text;
  v_expected jsonb;
  v_sources jsonb;
  v_work jsonb;
  v_count integer;
  v_authority bigint;
begin
  if new.activity_type not in ('קורס', 'course') or new.generation_kind is not null then
    new.course_business_identity := null;
    new.course_dashboard_sources := null;
    return new;
  end if;

  select u.emp_id::bigint, u.role into v_emp_id, v_role
  from public.users u
  where u.auth_user_id = auth.uid() and u.is_active = true
  limit 1;

  -- Manager corrections use the same team/month authorization as the write RPC.
  -- They must not be mistaken for an instructor reporting another employee.
  if tg_op = 'UPDATE'
     and new.emp_id is not distinct from old.emp_id
     and new.activity_type is not distinct from old.activity_type
     and new.course_business_identity is not distinct from old.course_business_identity
     and new.course_dashboard_sources is not distinct from old.course_dashboard_sources
     and new.activity_row_id is not distinct from old.activity_row_id
     and new.activity_id is not distinct from old.activity_id
     and new.activity_no is not distinct from old.activity_no
     and new.school_id is not distinct from old.school_id
     and new.authority_id is not distinct from old.authority_id
     and v_role in ('admin', 'operation_manager', 'activities_manager', 'manager', 'instructor_manager')
     and public.attendance_manager_can_review_employee(old.emp_id)
     and public.attendance_manager_month_allows_mutation(old.emp_id, old.report_date)
     and public.attendance_manager_month_allows_mutation(new.emp_id, new.report_date) then
    if new.report_date is distinct from old.report_date and new.course_business_identity is not null then
      v_sources := attendance_private.course_sources(new.emp_id, new.report_date, new.course_business_identity);
      if jsonb_array_length(v_sources) = 0 then
        raise exception 'הקורס אינו משויך למדריך בתאריך המדווח בדשבורד' using errcode='42501';
      end if;
      new.course_dashboard_sources := v_sources;
    end if;
    return new;
  end if;

  -- Expense/notes/travel corrections do not alter the dashboard assignment.
  if tg_op = 'UPDATE' then
    if old.emp_id is not distinct from new.emp_id
       and old.report_date is not distinct from new.report_date
       and old.activity_row_id is not distinct from new.activity_row_id
       and old.activity_type is not distinct from new.activity_type
       and old.school_id is not distinct from new.school_id
       and old.authority_id is not distinct from new.authority_id
       and old.course_business_identity is not distinct from new.course_business_identity
       and old.course_dashboard_sources is not distinct from new.course_dashboard_sources
       and (old.course_business_identity is null or (
         old.activity_id is not distinct from new.activity_id
         and old.activity_no is not distinct from new.activity_no
         and old.start_time is not distinct from new.start_time and old.end_time is not distinct from new.end_time
         and (old.total_hours is not distinct from new.total_hours
           or (old.course_dashboard_sources is not null
               and new.total_hours is not distinct from
                 (attendance_private.course_work(old.course_dashboard_sources)->>'total_hours')::numeric))
         and old.activity_name_snapshot is not distinct from new.activity_name_snapshot
         and old.meeting_no is not distinct from new.meeting_no)) then
      new := attendance_private.normalize_course_paid_hours(new, tg_op = 'UPDATE');
      return new;
    end if;
  end if;

  if new.course_business_identity is not null then
    if v_emp_id is null or new.emp_id is distinct from v_emp_id then
      raise exception 'לא ניתן לדווח קורס עבור מדריך אחר' using errcode='42501';
    end if;
    v_sources := attendance_private.course_sources(v_emp_id,new.report_date,new.course_business_identity);
    v_count := jsonb_array_length(v_sources);
    if v_count=0 then
      raise exception 'הקורס אינו משויך למדריך בתאריך המדווח בדשבורד' using errcode='42501';
    end if;
    v_work := attendance_private.course_work(v_sources);
    if v_work is null then raise exception 'נתוני שעות הקורס בדשבורד אינם תקינים' using errcode='22023'; end if;
    if new.school_id is distinct from (case when new.course_business_identity->1->>0='id'
      then (new.course_business_identity->1->>1)::bigint else null end) then
      raise exception 'בית הספר אינו תואם לפעילות בדשבורד' using errcode='42501';
    end if;
    select min(nullif(item->>'authority_id','')::bigint) into v_authority from jsonb_array_elements(v_sources) item;
    if exists(select 1 from jsonb_array_elements(v_sources) item
      where nullif(item->>'authority_id','')::bigint is distinct from v_authority)
      or new.authority_id is distinct from v_authority then
      raise exception 'הרשות אינה תואמת לפעילות בדשבורד' using errcode='42501';
    end if;
    -- Never trust client-supplied source links, meeting numbers or pay. Rebuild from the dashboard.
    new.course_dashboard_sources := v_sources;
    new.activity_name_snapshot := new.course_business_identity->>0;
    new.activity_row_id := case when v_count=1 then v_sources->0->>'row_id' else null end;
    new.activity_id := case when v_count=1 then (v_sources->0->>'id')::bigint else null end;
    new.activity_no := case when v_count=1 then v_sources->0->>'activity_no' else null end;
    new.meeting_no := case when v_count=1 then (v_sources->0->>'meeting_no')::int else null end;
    new.start_time := (v_work->>'start_time')::time;
    new.end_time := (v_work->>'end_time')::time;
    new.total_hours := (v_work->>'total_hours')::numeric;
    new := attendance_private.normalize_course_paid_hours(new, tg_op = 'UPDATE');
    return new;
  end if;
  -- JSON sources cannot be attached to a legacy single-row report by the client.
  new.course_dashboard_sources := null;
  -- Existing RLS continues to govern legacy manager/admin and service writes.
  if v_role is distinct from 'instructor' then return new; end if;

  if new.emp_id is distinct from v_emp_id then
    raise exception using errcode = '42501', message = 'לא ניתן לדווח קורס עבור מדריך אחר';
  end if;

  select item into v_expected
  from jsonb_array_elements(public.av2_get_current_instructor_activity_choices_for_date(new.report_date)) item
  where item->>'row_id' = btrim(coalesce(new.activity_row_id, ''))
    and lower(btrim(item->>'activity_type')) in ('course', 'קורס');

  if v_expected is null then
    raise exception using errcode = '42501', message = 'הקורס אינו משויך למדריך בתאריך המדווח בדשבורד';
  end if;

  if nullif(v_expected->>'single_school_id', '') is not null then
    if new.school_id is distinct from (v_expected->>'single_school_id')::bigint then
      raise exception using errcode = '42501', message = 'בית הספר אינו תואם לפעילות בדשבורד';
    end if;
  elsif jsonb_array_length(coalesce(nullif(v_expected->'linked_schools_json', 'null'::jsonb), '[]'::jsonb)) > 0 then
    if not exists (
      select 1 from jsonb_array_elements(v_expected->'linked_schools_json') school
      where (school->>'id')::bigint = new.school_id
    ) then
      raise exception using errcode = '42501', message = 'בית הספר אינו תואם לפעילות בדשבורד';
    end if;
  end if;

  if new.authority_id is distinct from nullif(v_expected->>'authority_id', '')::bigint then
    raise exception using errcode = '42501', message = 'הרשות אינה תואמת לפעילות בדשבורד';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.av2_guard_generated_attendance_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('INSERT','UPDATE') and new.generation_kind in ('travel_time_cancellation','daily_travel_cancellation')
    and current_setting('app.av2_compensation_write',true) is distinct from '1' then
    raise exception 'attendance_generated_record_protected' using errcode='42501';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION public.av2_guard_reviewed_inline_cancellation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.cancellation_before_minutes is distinct from new.cancellation_before_minutes
     or old.cancellation_after_minutes is distinct from new.cancellation_after_minutes then
    if exists (
      select 1 from public.attendance_travel_compensations c
      where c.source_attendance_record_id = old.id
        and c.review_status in ('approved', 'corrected', 'rejected')
    ) then
      raise exception 'attendance_travel_review_locked' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.av2_mark_source_travel_pending_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor_emp bigint;
  route_context_changed boolean := false;
begin
  if new.generation_kind is not null then return new; end if;
  select emp_id::bigint into actor_emp
  from public.users
  where auth_user_id = auth.uid() and is_active = true
  limit 1;

  if tg_op = 'INSERT' then
    route_context_changed := true;
  else
    route_context_changed := old.activity_type is distinct from new.activity_type
      or old.activity_name_snapshot is distinct from new.activity_name_snapshot
      or old.activity_row_id is distinct from new.activity_row_id
      or old.authority_id is distinct from new.authority_id
      or old.authority_name_snapshot is distinct from new.authority_name_snapshot
      or old.school_id is distinct from new.school_id
      or old.school_name_snapshot is distinct from new.school_name_snapshot
      or old.destination_address_snapshot is distinct from new.destination_address_snapshot
      or old.training_mode is distinct from new.training_mode
      or old.training_schedule_id is distinct from new.training_schedule_id;
  end if;

  if actor_emp = new.emp_id and route_context_changed then
    if tg_op = 'UPDATE' then
      perform set_config('app.av2_compensation_write', '1', true);
      delete from public.attendance_records child
      where child.source_attendance_record_id = new.id
        and child.generation_kind = 'travel_time_cancellation';
      delete from public.attendance_travel_compensations
      where source_attendance_record_id = new.id;
    end if;
    perform public.av2_prepare_attendance_travel(new.id, auth.uid());
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.av2_sync_operation_destination_address()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  operation_address text;
  scheduled_training public.instructor_training_schedule%rowtype;
  normalized_type text;
  normalized_name text;
begin
  if new.generation_kind is not null then return new; end if;

  normalized_type := regexp_replace(lower(btrim(coalesce(new.activity_type, ''))), '\s+', '', 'g');
  normalized_name := regexp_replace(lower(btrim(coalesce(new.activity_name_snapshot, ''))), '\s+', '', 'g');
  if normalized_type <> 'תפעול' then new.operation_meeting_mode := null; end if;

  if normalized_type = 'הכשרה' and new.training_schedule_id is not null then
    select * into scheduled_training
    from public.instructor_training_schedule t
    where t.id = new.training_schedule_id
      and t.is_active = true
      and t.training_date = new.report_date
      and (t.emp_id = new.emp_id or t.participant_scope = 'open');
    if not found then
      raise exception 'attendance_training_schedule_invalid' using errcode = '42501';
    end if;
    new.training_mode := case when scheduled_training.is_online then 'online' else 'physical' end;
    new.authority_id := null;
    new.authority_name_snapshot := case
      when scheduled_training.is_online then null
      else nullif(btrim(scheduled_training.location_name), '')
    end;
    new.school_id := null;
    new.school_name_snapshot := null;
    new.semel_mosad := null;
    if scheduled_training.is_online then
      new.roundtrip_km := 0;
      new.public_transport := false;
      new.public_transport_cost := 0;
    end if;
    new.destination_address_snapshot := case
      when scheduled_training.is_online then null
      else nullif(btrim(scheduled_training.location_address), '')
    end;
  elsif normalized_type = 'הכשרה' and new.training_mode = 'online' then
    new.roundtrip_km := 0;
    new.public_transport := false;
    new.public_transport_cost := 0;
    new.authority_id := null;
    new.authority_name_snapshot := null;
    new.school_id := null;
    new.school_name_snapshot := null;
    new.semel_mosad := null;
    new.destination_address_snapshot := null;
  elsif normalized_type = 'תפעול' then
    if normalized_name = 'צוות' then
      if new.operation_meeting_mode is null or new.operation_meeting_mode not in ('online', 'physical') then
        raise exception 'attendance_team_meeting_mode_required' using errcode = '23514';
      end if;
      if new.operation_meeting_mode = 'online' then
        new.destination_address_snapshot := null;
        new.roundtrip_km := 0;
        new.public_transport := false;
        new.public_transport_cost := 0;
      else
        new.destination_address_snapshot := nullif(btrim(new.destination_address_snapshot), '');
        if new.destination_address_snapshot is null then
          raise exception 'attendance_team_physical_location_required' using errcode = '23514';
        end if;
      end if;
    else
      new.operation_meeting_mode := null;
      select nullif(btrim(o.address), '') into operation_address
      from public.attendance_operation_options o
      where lower(btrim(o.label)) = lower(btrim(coalesce(new.activity_name_snapshot, '')))
      limit 1;
      new.destination_address_snapshot := operation_address;
    end if;
  elsif normalized_type = 'הכשרה'
    and normalized_name = regexp_replace(lower('הכשרת בסיס'), '\s+', '', 'g') then
    new.destination_address_snapshot := '6RVR+XM, יקום';
  elsif normalized_type = 'הכשרה' and new.training_mode = 'physical' then
    -- Preserve the instructor's explicit venue for ordinary physical training.
    new.destination_address_snapshot := nullif(btrim(new.destination_address_snapshot), '');
  else
    new.destination_address_snapshot := null;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.av2_can_write_month(p_report_date date)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_emp_id bigint;
  v_month_key text;
  v_status text;
  v_cur_year int := extract(year from current_date)::int;
  v_cur_month int := extract(month from current_date)::int;
  v_cur_day int := extract(day from current_date)::int;
  v_rec_year int := extract(year from p_report_date)::int;
  v_rec_month int := extract(month from p_report_date)::int;
  v_prev_year int;
  v_prev_month int;
begin
  select emp_id::bigint
    into v_emp_id
  from public.users
  where auth_user_id = auth.uid()
    and is_active = true
  limit 1;

  if v_emp_id is null then
    return false;
  end if;

  v_month_key := to_char(p_report_date, 'YYYY-MM');

  select coalesce(nullif(trim(status), ''), 'open')
    into v_status
  from public.attendance_month_approvals
  where emp_id = v_emp_id
    and month_key = v_month_key
  limit 1;

  if exists (
    select 1
    from public.payroll_control_approvals pca
    where pca.employee_id = v_emp_id::text
      and pca.month_key = v_month_key
      and pca.status = 'approved_for_payroll'
  ) then
    return false;
  end if;

  if v_status in ('submitted', 'locked') then
    return false;
  end if;

  if v_status = 'reopened' then
    return true;
  end if;

  if v_rec_year = v_cur_year and v_rec_month = v_cur_month then
    return true;
  end if;

  if v_cur_month = 1 then
    v_prev_year := v_cur_year - 1;
    v_prev_month := 12;
  else
    v_prev_year := v_cur_year;
    v_prev_month := v_cur_month - 1;
  end if;

  if v_rec_year = v_prev_year
     and v_rec_month = v_prev_month
     and v_cur_day <= 2 then
    return true;
  end if;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.av2_attendance_record_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_emp_id bigint;
  v_internal_compensation_write boolean := coalesce(current_setting('app.av2_compensation_write', true), '') = '1';
  v_manager_review_write boolean := coalesce(current_setting('app.av2_manager_attendance_write', true), '') = '1';
begin
  if v_internal_compensation_write
     and new.generation_kind in ('travel_time_cancellation','daily_travel_cancellation')
     and new.source_attendance_record_id is not null then
    if new.emp_id is null or not exists (
      select 1
      from public.attendance_records source_row
      where source_row.id = new.source_attendance_record_id
        and source_row.emp_id = new.emp_id
        and source_row.generation_kind is null
    ) then
      raise exception 'Invalid generated travel cancellation source';
    end if;
    return new;
  end if;

  if v_manager_review_write then
    if new.emp_id is null
       or new.generation_kind is not null
       or new.source_attendance_record_id is not null
       or not public.attendance_manager_can_review_employee(new.emp_id)
       or not public.attendance_manager_month_allows_mutation(new.emp_id, new.report_date) then
      raise exception 'payroll_attendance_permission_denied' using errcode = '42501';
    end if;
    return new;
  end if;

  select emp_id::bigint
    into v_emp_id
  from public.users
  where auth_user_id = auth.uid()
  limit 1;

  if v_emp_id is null then
    raise exception 'No authenticated user or missing users mapping';
  end if;

  new.emp_id := v_emp_id;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.av2_prepare_attendance_travel(p_source_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ctx jsonb;
  old public.attendance_travel_compensations%rowtype;
  changed boolean;
  locked_decision boolean;
  before_json jsonb;
begin
  ctx := public.av2_attendance_travel_context(p_source_id, p_actor_id);

  -- Never create or delete legacy compensation rows after the daily-travel cutover.
  -- Existing November residuals stay readable; new writes go through daily travel only.
  if coalesce(ctx->>'reason', '') = 'daily_travel_cutover' then
    return ctx;
  end if;

  select * into old
  from public.attendance_travel_compensations
  where source_attendance_record_id = p_source_id
  for update;

  locked_decision := found and old.review_status in ('approved', 'corrected', 'rejected');

  -- Physical → online / ineligible: never delete locked manager decisions or their payables.
  if not coalesce((ctx->>'eligible')::boolean, false) then
    if not found then
      return ctx;
    end if;
    if locked_decision then
      before_json := public.av2_travel_compensation_snapshot(old);
      perform set_config('app.av2_compensation_write', '1', true);
      update public.attendance_travel_compensations
      set calculation_status = 'unavailable',
          failure_code = 'context_not_eligible',
          -- Keep NOT NULL fingerprint; mark ineligible without wiping locked pay.
          route_context_fingerprint = coalesce(
            old.route_context_fingerprint,
            'ineligible:' || p_source_id::text
          ),
          origin_entity_key = null,
          destination_entity_key = null,
          outbound_travel_minutes = null,
          return_travel_minutes = null,
          calculated_cancellation_minutes = null,
          system_distance_km = null,
          updated_at = now()
      where source_attendance_record_id = p_source_id
      returning * into old;
      perform public.av2_append_travel_compensation_event(
        p_source_id, old.emp_id, 'route_recalculated', before_json,
        public.av2_travel_compensation_snapshot(old),
        'preserve locked decision after ineligible context'
      );
      return ctx || jsonb_build_object(
        'context_changed', true,
        'locked_decision_preserved', true,
        'review_status', old.review_status,
        'approved_cancellation_minutes', old.approved_cancellation_minutes
      );
    end if;

    perform set_config('app.av2_compensation_write', '1', true);
    if old.generated_attendance_record_id is not null then
      delete from public.attendance_records where id = old.generated_attendance_record_id;
    end if;
    delete from public.attendance_travel_compensations
    where source_attendance_record_id = p_source_id;
    return ctx;
  end if;

  changed := not found or old.route_context_fingerprint is distinct from ctx->>'fingerprint';

  if changed then
    perform set_config('app.av2_compensation_write', '1', true);
    if found and old.generated_attendance_record_id is not null and not locked_decision then
      delete from public.attendance_records where id = old.generated_attendance_record_id;
    end if;

    insert into public.attendance_travel_compensations(
      source_attendance_record_id, emp_id, calculation_status, route_context_fingerprint,
      origin_entity_key, destination_entity_key,
      reported_outbound_minutes, reported_return_minutes, reported_at, reported_by,
      review_status, approved_cancellation_minutes, review_by, review_at, review_note,
      manually_overridden, override_by, override_at, generated_attendance_record_id,
      failure_code, final_cancellation_minutes, updated_at
    ) values (
      p_source_id, (ctx->>'emp_id')::bigint, 'pending', ctx->>'fingerprint',
      ctx->>'origin_entity_key', ctx->>'destination_entity_key',
      null, null, null, null,
      'none', null, null, null, null,
      false, null, null,
      case when locked_decision then old.generated_attendance_record_id else null end,
      null, 0, now()
    )
    on conflict (source_attendance_record_id) do update set
      calculation_status = 'pending',
      route_context_fingerprint = excluded.route_context_fingerprint,
      origin_entity_key = excluded.origin_entity_key,
      destination_entity_key = excluded.destination_entity_key,
      outbound_travel_minutes = null,
      return_travel_minutes = null,
      calculated_cancellation_minutes = null,
      system_distance_km = null,
      failure_code = null,
      -- Preserve guide report.
      reported_outbound_minutes = public.attendance_travel_compensations.reported_outbound_minutes,
      reported_return_minutes = public.attendance_travel_compensations.reported_return_minutes,
      reported_at = public.attendance_travel_compensations.reported_at,
      reported_by = public.attendance_travel_compensations.reported_by,
      -- Preserve locked manager decision; otherwise recompute later after system calc.
      review_status = case
        when public.attendance_travel_compensations.review_status in ('approved', 'corrected', 'rejected')
          then public.attendance_travel_compensations.review_status
        when public.attendance_travel_compensations.reported_outbound_minutes is not null
          then 'pending_review'
        when exists (
          select 1 from public.attendance_records sr
          where sr.id = p_source_id and sr.cancellation_before_minutes is not null
        ) then 'pending_review'
        else 'none'
      end,
      approved_cancellation_minutes = case
        when public.attendance_travel_compensations.review_status in ('approved', 'corrected', 'rejected')
          then public.attendance_travel_compensations.approved_cancellation_minutes
        else null
      end,
      review_by = public.attendance_travel_compensations.review_by,
      review_at = public.attendance_travel_compensations.review_at,
      review_note = public.attendance_travel_compensations.review_note,
      manually_overridden = public.attendance_travel_compensations.manually_overridden,
      override_by = public.attendance_travel_compensations.override_by,
      override_at = public.attendance_travel_compensations.override_at,
      generated_attendance_record_id = case
        when public.attendance_travel_compensations.review_status in ('approved', 'corrected')
          then public.attendance_travel_compensations.generated_attendance_record_id
        else null
      end,
      final_cancellation_minutes = case
        when public.attendance_travel_compensations.review_status in ('approved', 'corrected')
          then public.attendance_travel_compensations.final_cancellation_minutes
        else 0
      end,
      updated_at = now();
  end if;

  if changed then
    return ctx || jsonb_build_object('context_changed', true, 'calculation_status', 'pending');
  end if;
  return ctx || (to_jsonb(old) - 'source_attendance_record_id' - 'emp_id')
           || jsonb_build_object('context_changed', false);
end;
$function$

CREATE OR REPLACE FUNCTION attendance_private.normalize_course_paid_hours(p_row attendance_records, p_is_update boolean)
 RETURNS attendance_records
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_source jsonb;
  v_work jsonb;
begin
  if p_row.activity_type is distinct from 'קורס'
     or p_row.generation_kind is not null
     or jsonb_typeof(p_row.course_dashboard_sources) is distinct from 'array'
     or jsonb_array_length(p_row.course_dashboard_sources) = 0 then
    return p_row;
  end if;

  -- Every linked source must belong to this employee and reporting date.
  for v_source in select value from jsonb_array_elements(p_row.course_dashboard_sources) loop
    if v_source->>'activity_type' is distinct from 'course'
       or v_source->>'report_date' is distinct from p_row.report_date::text
       or v_source->>'resolved_emp_id' is distinct from p_row.emp_id::text
       or coalesce(v_source->>'start_time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
       or coalesce(v_source->>'end_time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
      return p_row;
    end if;
  end loop;
  v_work := attendance_private.course_work(p_row.course_dashboard_sources);
  if v_work is null then return p_row; end if;

  -- Do not rewrite approved reports or already approved/locked months.
  if p_is_update and exists (
    select 1 from public.attendance_manager_record_reviews r
    where r.record_id = p_row.id and r.status = 'approved'
  ) then
    return p_row;
  end if;
  if exists (
    select 1 from public.attendance_month_approvals m
    where m.emp_id = p_row.emp_id
      and m.month_key = to_char(p_row.report_date,'YYYY-MM')
      and (m.manager_approved_at is not null or m.status = 'locked')
  ) then
    return p_row;
  end if;
  p_row.total_hours := (v_work->>'total_hours')::numeric;
  return p_row;
end
$function$

CREATE OR REPLACE FUNCTION public.attendance_manager_can_review_employee(p_employee_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_own_name text;
  v_manager_name text;
begin
  select
    lower(trim(coalesce(u.role, ''))),
    coalesce(
      nullif(trim(coalesce(u.full_name, '')), ''),
      nullif(trim(coalesce(u.name, '')), ''),
      nullif(trim(coalesce(u.username, '')), '')
    )
  into v_role, v_own_name
  from public.users u
  where u.auth_user_id = auth.uid()
    and u.is_active = true
  limit 1;

  if v_role is null then return false; end if;
  if v_role in ('admin', 'operation_manager') then return true; end if;
  if v_role not in ('activities_manager', 'manager', 'instructor_manager') then return false; end if;

  select coalesce(ci.direct_manager, '')
  into v_manager_name
  from public.contacts_instructors ci
  where ci.emp_id = p_employee_id
  limit 1;

  if not found then return false; end if;
  return lower(trim(coalesce(v_manager_name, ''))) = lower(trim(coalesce(v_own_name, '')));
end;
$function$

CREATE OR REPLACE FUNCTION public.attendance_manager_month_allows_mutation(p_emp_id bigint, p_report_date date)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_status text;
begin
  if p_emp_id is null or p_report_date is null then
    return false;
  end if;

  select lower(trim(coalesce(u.role, '')))
  into v_role
  from public.users u
  where u.auth_user_id = auth.uid()
    and u.is_active = true
  limit 1;

  if v_role is null then
    return false;
  end if;

  if v_role in ('admin', 'operation_manager') then
    return true;
  end if;

  select coalesce(nullif(trim(ama.status), ''), 'open')
  into v_status
  from public.attendance_month_approvals ama
  where ama.emp_id = p_emp_id
    and ama.month_key = to_char(p_report_date, 'YYYY-MM')
  limit 1;

  if not found or v_status <> 'submitted' then
    return false;
  end if;

  if public.av2_attendance_month_is_closed(p_emp_id, p_report_date) then
    return false;
  end if;

  return true;
end;
$function$
